"""
Generate the catalog index from the model entries, so it can't drift from the code.

    python3 -m ode_catalog.index
"""

from pathlib import Path

from ode_catalog import CATALOG

INDEX_PATH = Path(__file__).parent / "INDEX.md"


def _source(entry):
    return entry.reference.citation if entry.reference else "Not from a publication"


def _unit(entry):
    return entry.time_unit or "not recorded"


def render_index():
    """Return the catalog index as Markdown."""
    lines = [
        "# Model catalog",
        "",
        "Generated by `python3 -m ode_catalog.index`. Don't edit this file by hand.",
        "",
        "| Model | Name | Domain | Version | States | Time unit | Status | Scenarios |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for model_id, entry in sorted(CATALOG.items()):
        states = ", ".join(state.key for state in entry.states)
        scenarios = ", ".join(
            f"**{s.name}**" if s.name == entry.default_scenario else s.name for s in entry.scenarios
        )
        lines.append(
            f"| [{model_id}]({model_id}/README.md) | {entry.name} | {entry.domain} | {entry.version} "
            f"| {states} | {_unit(entry)} | {entry.status.value} | {scenarios} |"
        )
    lines += ["", "The default scenario is in bold.", "", "## Sources, evidence and open items", ""]
    for model_id, entry in sorted(CATALOG.items()):
        lines += [
            f"### {model_id}",
            "",
            f"- **Source:** {_source(entry)}",
            f"- **Evidence:** {entry.evidence or 'The contract tests pass.'}",
        ]
        if entry.todo:
            lines.append("- **Not verified:**")
            lines += [f"  - {item}" for item in entry.todo]
        lines.append("")
    return "\n".join(lines)


def main():
    INDEX_PATH.write_text(render_index(), encoding="utf-8")
    print(f"Wrote {INDEX_PATH}")


if __name__ == "__main__":
    main()
